/* Iterative dominators for graph with source vertex zero; max 30 vertices. */
#include <stdio.h>
int main(void){int n,m,adj[30][30]={0},reach[30]={0},q[30],h=0,t=0;unsigned dom[30];if(scanf("%d%d",&n,&m)!=2||n<1||n>30||m<0||m>900)return 1;for(int i=0;i<m;i++){int a,b;if(scanf("%d%d",&a,&b)!=2||a<0||a>=n||b<0||b>=n)return 1;adj[a][b]=1;}q[t++]=0;reach[0]=1;while(h<t){int u=q[h++];for(int v=0;v<n;v++)if(adj[u][v]&&!reach[v])reach[v]=1,q[t++]=v;}unsigned all=(1u<<n)-1u;for(int i=0;i<n;i++)dom[i]=i==0?1u:all;int changed=1;while(changed){changed=0;for(int v=1;v<n;v++)if(reach[v]){unsigned d=all;int preds=0;for(int u=0;u<n;u++)if(reach[u]&&adj[u][v])d&=dom[u],preds++;d=(preds?d:0)|(1u<<v);if(d!=dom[v])dom[v]=d,changed=1;}}for(int i=0;i<n;i++){if(!reach[i]){printf("%d: unreachable\n",i);continue;}printf("%d:",i);for(int j=0;j<n;j++)if(dom[i]&(1u<<j))printf(" %d",j);putchar('\n');}return 0;}